head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellDisplayData]<br/>Row 인덱스와 Column 정보를 사용하여 Display 포맷이 적용된 Body Cell 데이터를 반환합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 데이터를 조회할 Cell 의 Row 인덱스값을 설정해야 합니다. (0 부터 시작, 필터/정렬 적용 상태 기준)",
        "columnInfo(필수) 파라미터로 데이터를 조회할 Cell 의 Column ID 또는 인덱스값을 설정해야 합니다. (인덱스는 0 부터 시작)",
        "파라미터에 해당하는 Body Cell 데이터(Display 포맷 적용)를 반환해야 합니다.",
        "inputType 이 'checkbox' / 'image' / 'radio' 인 Cell 은 원본 데이터 그대로 반환해야 합니다.",
        "inputType 이 'select' / 'checkcombobox' / 'autoComplete'(ItemSet 기반) 인 Cell 은 Label 값을 반환해야 합니다.",
        "inputType 이 'expression' 인 Cell 은 산식 계산 후 Formatter 를 적용하여 반환해야 합니다.",
        "inputType 이 'secret' 인 Cell 은 모든 문자를 '●' 로 반환해야 합니다.",
        "Cell 데이터가 null 이면 빈 문자열('') 을 반환해야 합니다.",
        "파라미터가 유효하지 않으면 빈 문자열('') 또는 undefined 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 inputType 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="Column 인덱스 - 0:name(text) / 1:grade(select, value→label) / 2:amount(number displayFormat #,###) / 3:bonus(expression, amount*2) / 4:pw(secret) / 5:agree(checkbox). Row2 의 name 은 null."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - grade : select 컬럼 value (A/B/C) - GridView choices 에서 Label(브론즈/실버/골드) 로 변환
    // - amount : number, displayFormat 적용 대상
    // - pw : secret 컬럼 원본 문자열
    // - agree : checkbox 컬럼 원본값(1/0)
    // - Row2 의 name 은 null (null -> '' 검증)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="pw" name="pw" dataType="text"></w2:column>';
    strDlt += '<w2:column id="agree" name="agree" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "grade": "A", "amount": 23456, "pw": "abcd",   "agree": "1" },
        { "name": "Jane", "grade": "B", "amount": 12000, "pw": "secret", "agree": "0" },
        { "name": null,   "grade": "C", "amount": 8500,  "pw": "12345",  "agree": "1" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 6컬럼 + gBody, 다양한 inputType 컬럼으로 @return 각 케이스 검증)
    // 마지막 agree 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:680px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getCellDisplayData 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol2" value="등급"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol4" value="보너스"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol5" value="비밀"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol6" value="동의"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text) - 원본값, Row2 는 null -> ""
    strTarget += '<w2:column width="110" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : grade (select, ItemSet) - 원본 value(A/B/C) -> Label(브론즈/실버/골드) 반환
    strTarget += '<w2:column width="110" style="" inputType="select" id="grade" dataList="grade">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>브론즈</w2:label><w2:value>A</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>실버</w2:label><w2:value>B</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>골드</w2:label><w2:value>C</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    // index 2 : amount (number + displayFormat) - 원본 23456 -> "23,456"
    strTarget += '<w2:column width="110" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    // index 3 : bonus (expression) - amount * 2 산식 계산 + Formatter(#,###)
    strTarget += '<w2:column width="110" style="" inputType="expression" dataType="number" displayFormat="#,###" id="bonus" expression="Number(display(\'amount\'))*2"></w2:column>';
    // index 4 : pw (secret) - 모든 문자를 "●" 로 반환
    strTarget += '<w2:column width="110" style="" inputType="secret" id="pw" dataList="pw"></w2:column>';
    // index 5 : agree (checkbox) - 원본값 그대로 반환
    strTarget += '<w2:column width="*" style="" inputType="checkbox" id="agree" dataList="agree" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getCellDisplayData 확인 : par_rowIndex / par_columnInfo(컬럼 인덱스) 로 호출 -> Display 포맷 적용된 Body Cell 데이터 반환
// - 인덱스 1(grade, select)     : 원본 value -> Label 반환
// - 인덱스 2(amount, number)    : displayFormat 적용값 반환 (23456 -> "23,456")
// - 인덱스 3(bonus, expression) : 산식 계산 후 Formatter 적용값 반환
// - 인덱스 4(pw, secret)        : 모든 문자 "●" 반환
// - 인덱스 5(agree, checkbox)   : 원본값 그대로 반환
// - Row2 의 name(인덱스0) 은 null -> "" 반환
scwin.btn_getCellDisplayData_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // columnInfo 는 컬럼 인덱스(Number) 로 전달
    let colIndex = Number(par_columnInfo.getValue());
    let rtn = target1.getCellDisplayData(rowIndex, colIndex);
    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("getCellDisplayData(" + rowIndex + ", " + colIndex + ") : '" + rtn + "'");
}



// 유효하지 않은 파라미터 : 범위를 벗어난 rowIndex / colIndex -> "" 또는 undefined 반환
scwin.btn_getInvalid_onclick = function () {
    let rtn = target1.getCellDisplayData(99, 99);
    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[유효하지 않은 파라미터] getCellDisplayData(99, 99) : '" + rtn + "'");
}
